// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { encodeWorkspace } from "../../../main/frontend/graph-explorer/workspace-format.ts";
import { parseWorkspacePayload } from "../../../main/frontend/graph-explorer/workspace.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { mergeStatementLinks, statementLinksOf } from "../../../main/frontend/graph-explorer/statement-links.ts";

const uri = (value) => ({ type: "uri", value });
const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });

function sampleGraph(size) {
  const rows = [
    row(uri("urn:alice"), "urn:knows", uri("urn:bob")),
    row(uri("urn:alice"), "urn:name", { type: "literal", value: "Alice \"A\"", "xml:lang": "EN-gb" }),
    row(uri("urn:alice"), "urn:age", { type: "literal", value: "39", datatype: "http://www.w3.org/2001/XMLSchema#integer" }),
    row(uri("urn:alice"), "urn:address", { type: "bnode", value: "b1" }),
    row({ type: "bnode", value: "b1" }, "urn:street", { type: "literal", value: "" }),
    {
      source: uri("urn:claim"),
      predicate: uri("http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies"),
      target: { type: "triple", value: { subject: uri("urn:alice"), predicate: uri("urn:knows"), object: uri("urn:bob") } },
    },
  ];
  for (let index = 0; index < size; index += 1) rows.push(row(uri(`http://example.org/n${index}`), "http://example.org/links", uri(`http://example.org/n${(index * 7 + 1) % size}`)));
  let graph = mergeStatementLinks(mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows), false, "batch-1"), statementLinksOf(rows), "batch-1");
  graph = {
    ...graph,
    nodes: graph.nodes.map((node, index) => ({
      ...node,
      x: index * 10.123456,
      y: -index,
      ...(index === 0 ? { pinned: true, types: [{ id: "urn:Person", label: "Person" }] } : {}),
    })),
  };
  return {
    graph,
    transform: { x: 1, y: 2, k: 0.5 },
    query: "CONSTRUCT WHERE { ?s ?p ?o }",
    endpointId: "rdf4j:repo",
    customUrl: "",
    provenanceBatches: [{ id: "batch-1", label: "SPARQL result", endpoint: "/wb/graph", query: "q", tripleCount: 6, loadedAt: "2026-10-15T00:00:00.000Z", limit: null, complete: true }],
    namedGroups: [{ id: "g1", name: "Group", color: "#123456", nodeIds: ["urn:alice", "urn:bob"] }],
    selectedNodeIds: ["urn:bob"],
    focusedNodeId: "urn:alice",
    scope: "all",
    savedAt: "2026-10-15T00:00:00.000Z",
  };
}

test("the compact form restores the same graph, positions to two decimals", () => {
  const payload = sampleGraph(20);
  const restored = parseWorkspacePayload(encodeWorkspace(payload));
  const round = (value) => Math.round(value * 100) / 100;
  // As JSON: keys holding undefined and the sign of zero are not part of a graph.
  const plain = (value) => JSON.parse(JSON.stringify(value));
  assert.deepEqual(plain(restored.graph.nodes), plain(payload.graph.nodes.map((node) => ({ ...node, x: round(node.x), y: round(node.y) }))));
  assert.deepEqual(restored.graph.edges, payload.graph.edges);
  assert.deepEqual(restored.graph.statementLinks, payload.graph.statementLinks);
  for (const key of ["transform", "query", "provenanceBatches", "namedGroups", "selectedNodeIds", "focusedNodeId", "scope", "savedAt"])
    assert.deepEqual(restored[key], payload[key], key);
});

test("a large graph takes a fraction of the space of the plain form", () => {
  const payload = sampleGraph(20000);
  const compact = encodeWorkspace(payload);
  const plain = JSON.stringify(payload);
  assert.ok(compact.length < plain.length / 3, `${compact.length} vs ${plain.length}`);
  assert.equal(parseWorkspacePayload(compact).graph.edges.length, payload.graph.edges.length);
});

test("tampered compact data is rejected like tampered plain data", () => {
  const encoded = JSON.parse(encodeWorkspace(sampleGraph(5)));
  encoded.predicates[0][0] = "urn:bad> } DROP ALL {";
  assert.equal(parseWorkspacePayload(JSON.stringify(encoded)), null);
  const outOfRange = JSON.parse(encodeWorkspace(sampleGraph(5)));
  outOfRange.edges[0] = 99999;
  assert.equal(parseWorkspacePayload(JSON.stringify(outOfRange)), null);
});

test("saving again after only the view changed does not encode the graph again", () => {
  const payload = sampleGraph(20);
  let reads = 0;
  const nodes = payload.graph.nodes;
  const graph = { ...payload.graph };
  Object.defineProperty(graph, "nodes", { enumerable: true, get: () => ((reads += 1), nodes) });
  const first = encodeWorkspace({ ...payload, graph });
  const readsAfterFirst = reads;
  const moved = { ...payload, graph, transform: { x: 40, y: -3, k: 2 }, selectedNodeIds: [] };
  const second = encodeWorkspace(moved);
  assert.equal(reads, readsAfterFirst, "the graph's nodes were not walked again");
  assert.deepEqual(parseWorkspacePayload(second).transform, { x: 40, y: -3, k: 2 });
  assert.equal(second, encodeWorkspace({ ...moved, graph: { ...payload.graph } }), "same text as a fresh encoding");
  assert.notEqual(first, second);
});

test("old compact workspaces restore the same language literal ID and merge without a duplicate", () => {
  const oldId = '__rdf_literal__:{"type":"literal","value":"Hello","datatype":"","language":"en"}';
  const oldWorkspace = {
    version: 2,
    query: "",
    endpointId: "rdf4j:repo",
    customUrl: "",
    provenanceBatches: [],
    namedGroups: [],
    selectedNodeIds: [oldId],
    focusedNodeId: oldId,
    scope: "all",
    savedAt: null,
    revision: 1,
    types: [],
    nodes: [["urn:alice", "Alice", 0], [0, "Hello", 1, null, null, null, "Hello", null, "en"]],
    predicates: [["urn:name", "name"]],
    batchIds: [],
    edges: [0, 0, 1, -1],
    edgeIds: {},
    edgeLabels: {},
    transform: { x: 0, y: 0, k: 1 },
  };
  const restored = parseWorkspacePayload(JSON.stringify(oldWorkspace));
  assert.equal(restored.graph.nodes[1].id, oldId);
  assert.equal(restored.graph.nodes[1].direction, undefined);

  const merged = mergeTriples(
    restored.graph,
    bindingsToTriples([
      row(uri("urn:alice"), "urn:name", { type: "literal", value: "Hello", "xml:lang": "EN" }),
    ]),
  );
  assert.equal(merged.nodes.length, 2);
  assert.equal(merged.edges.length, 1);
  assert.equal(merged.nodes[1].id, oldId);

  const reencoded = JSON.parse(encodeWorkspace({ ...restored, graph: merged }));
  assert.equal(reencoded.nodes[1].length, 9, "legacy nodes keep the version-2 language tuple columns");
  assert.equal(reencoded.nodes[1][8], "en");
});

test("directional terms pass from SPARQL bindings through graph nodes and compact persistence", () => {
  const term = { type: "literal", value: "مرحبا", "xml:lang": "ar", "its:dir": "rtl" };
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([row(uri("urn:alice"), "urn:name", term)]),
  );
  const literal = graph.nodes.find((node) => node.kind === "literal");
  assert.equal(literal.direction, "rtl");
  const restored = parseWorkspacePayload(encodeWorkspace({ ...sampleGraph(0), graph }));
  const restoredLiteral = restored.graph.nodes.find((node) => node.kind === "literal");
  assert.equal(restoredLiteral.id, literal.id);
  assert.equal(restoredLiteral.direction, "rtl");
});
